private void handleOutputFile(Path outFile, Parser handler, boolean isContentSource, XHTMLContentHandler xhtml, Metadata metadata, ParseContext context) throws IOException, SAXException, TikaException {
    if (handler != null) {
        ContentHandler target = isContentSource ? new BodyContentHandler(xhtml) : DISCARD_HANDLER;
        try (TikaInputStream tis = TikaInputStream.get(outFile)) {
            handler.parse(tis, target, metadata, context);
        }
    } else if (isContentSource) {
        // No handler — write raw file content as XHTML text
        try (BufferedReader reader = Files.newBufferedReader(outFile)) {
            String line = reader.readLine();
            while (line != null) {
                xhtml.characters(line);
                xhtml.newline();
                line = reader.readLine();
            }
        }
    }
}
